using ImageMagick;
using iText.Kernel.Geom;
using iText.Kernel.Pdf;
using PnpTool.Core;
using PnpTool.Core.Files;
using PnpTool.Core.Primitives;
using PnpTool.Core.Projects;
using PnpTool.Pdf.Layout;
using PnpTool.Pdf.Tools;
using Path = System.IO.Path;

namespace PnpTool.Pdf.Tests;

/// <summary>The PDF tools, run on documents generated by the program itself (A4, 3 × 3 cards of 180 × 252 points).</summary>
[Collection(GlobalState.Name)]
public sealed class PdfToolsTests : IDisposable
{
    private const double PageWidth = 595.28;
    private const double PageHeight = 841.89;
    private const double Left = (PageWidth - 540) / 2;
    private const double Bottom = (PageHeight - 756) / 2;

    private readonly Workspace _workspace = new();

    public void Dispose() => _workspace.Dispose();

    /// <summary>A generated deck without cut lines, written under the given name.</summary>
    private string Deck(string name, int cards, Action<Project>? configure = null)
    {
        Project project = _workspace.Project("Cartas_Standar.pnps", cards);
        project.Settings.Front.CutLine.LineType = CutLineType.None;
        project.Settings.Back.CutLine.LineType = CutLineType.None;
        project.Settings.InputParameters.OutputPdf = _workspace.File("out", name + ".pdf");
        configure?.Invoke(project);
        return PdfGenerator.Generate(project, _workspace.WorkFolder).Files[0];
    }

    private static string ColorOfCell(string file, int page, int column, int row) =>
        PdfInspection.ColorAt(file, page, Left + (column * 180) + 90, PageHeight - Bottom - (row * 252) - 126);

    // ------------------------------------------------------------ rasterising

    [Fact]
    public void Pages_render_without_ghostscript_at_the_resolution_asked()
    {
        string file = Deck("deck", 10);

        Assert.Equal(2, PdfRasterizer.PageCount(file));
        using MagickImage screen = PdfRasterizer.RenderPage(file, 0, 72);
        using MagickImage print = PdfRasterizer.RenderPage(file, 1, 144);

        Assert.InRange((int)screen.Width, 595, 596);
        Assert.InRange((int)screen.Height, 841, 842);
        Assert.InRange((int)print.Width, 1190, 1191);
        Assert.Equal(144, print.Density.X);
        Assert.Equal(MagickFormat.Png, print.Format);

        // First card of the first page, and the white of an empty cell on the second.
        using IPixelCollection<ushort> pixels = screen.GetPixels();
        IMagickColor<ushort> card = pixels.GetPixel((int)(Left + 90), (int)(Bottom + 126)).ToColor()!;
        Assert.Equal(255, card.R >> 8);
        Assert.Equal(0, card.G >> 8);
    }

    // ------------------------------------------------------------ extraction

    [Fact]
    public void Images_come_out_once_each_at_their_original_size_with_copies_in_the_name()
    {
        string file = Deck("deck", 3, project =>
        {
            project.Deck.Cards[1].Copies = 2;
            project.Deck.RecountCopies();
        });
        var extractor = new PdfImageExtractor { Destination = _workspace.File("images"), Files = [file] };

        AppError error = extractor.Extract(300);

        Assert.False(error.HasError, error.Message);
        Assert.Equal(3, extractor.Extracted.Count);
        Assert.Equal(["Img_0", "Img_1_X2", "Img_2"], extractor.Extracted.Select(path => Path.GetFileNameWithoutExtension(path)));
        for (int i = 0; i < 3; i++)
        {
            using var image = new MagickImage(extractor.Extracted[i]);
            Assert.Equal(180u, image.Width);
            Assert.Equal(252u, image.Height);
            using IPixelCollection<ushort> pixels = image.GetPixels();
            IMagickColor<ushort> color = pixels.GetPixel(90, 126).ToColor()!;
            string hex = $"#{color.R >> 8:X2}{color.G >> 8:X2}{color.B >> 8:X2}";
            Assert.True(PdfInspection.Close(Workspace.Colors[i], hex), hex);
        }

        // The copies in the name are what the program reads when the image is added to a deck.
        Assert.Equal(2, PnpTool.Core.Cards.Card.CopiesFromFileName(extractor.Extracted[1]));
    }

    [Fact]
    public void Whole_pages_come_out_as_one_image_per_page_at_the_resolution_asked()
    {
        string file = Deck("deck", 10);
        var progress = new List<int>();
        var extractor = new PdfImageExtractor
        {
            Destination = _workspace.File("pages"),
            Files = [file],
            WholePages = true,
            ReportProgress = progress.Add,
        };

        AppError error = extractor.Extract(100);

        Assert.False(error.HasError, error.Message);
        Assert.Equal([_workspace.File("pages", "deck_1.png"), _workspace.File("pages", "deck_2.png")], extractor.Extracted);
        using var page = new MagickImage(extractor.Extracted[0]);
        Assert.InRange((int)page.Width, 826, 828);    // 210 mm at 100 dpi
        Assert.InRange((int)page.Height, 1168, 1170);
        Assert.Equal(0, progress[0]);
    }

    [Fact]
    public void Extraction_can_invert_colours_and_empty_the_destination_first()
    {
        string file = Deck("deck", 1);
        Directory.CreateDirectory(_workspace.File("images"));
        File.WriteAllText(_workspace.File("images", "old.txt"), "left over");
        var extractor = new PdfImageExtractor
        {
            Destination = _workspace.File("images"),
            Files = [file],
            InvertColors = true,
            ClearDestination = true,
        };

        extractor.Extract(300);

        Assert.False(File.Exists(_workspace.File("images", "old.txt")));
        using var image = new MagickImage(Assert.Single(extractor.Extracted));
        using IPixelCollection<ushort> pixels = image.GetPixels();
        IMagickColor<ushort> color = pixels.GetPixel(90, 126).ToColor()!;
        Assert.True(color.R >> 8 < 12 && color.G >> 8 > 243 && color.B >> 8 > 243, $"{color.R >> 8},{color.G >> 8},{color.B >> 8}");   // red inverted is cyan
    }

    [Fact]
    public void Extracting_twice_does_not_overwrite_the_first_images()
    {
        string file = Deck("deck", 1);
        var extractor = new PdfImageExtractor { Destination = _workspace.File("images"), Files = [file] };

        extractor.Extract(300);
        string first = extractor.Extracted[0];
        extractor.Extract(300);

        Assert.NotEqual(first, extractor.Extracted[0]);
        Assert.EndsWith("Img_0_0.png", extractor.Extracted[0].Replace(".jpg", ".png"));
        Assert.True(File.Exists(first));
    }

    // ------------------------------------------------------------ merging

    [Fact]
    public void Files_are_joined_in_order_and_their_counts_added_up()
    {
        string first = Deck("first", 10);
        string second = Deck("second", 3);
        var steps = new List<int>();
        var merger = new PdfMerger { Sources = [first, second], Destination = _workspace.File("out", "joined.pdf") };
        merger.ProgressChanged += steps.Add;

        Assert.False(merger.Validate().HasError);
        merger.Merge();

        Assert.Equal(3, PdfInspection.PageCount(merger.Destination));
        Assert.Equal(9, PdfInspection.ImagesOn(merger.Destination, 1).Count);
        Assert.Equal(3, PdfInspection.ImagesOn(merger.Destination, 3).Count);
        Assert.Equal([0, 1, 2], steps);

        using var document = new PdfDocument(new PdfReader(merger.Destination));
        PdfDocumentInfo info = document.GetDocumentInfo();
        Assert.Equal("PNP Tool", info.GetAuthor());
        Assert.Equal("3", info.GetMoreInfo(PdfMetadataKeys.SheetCount));
        Assert.Equal("27", info.GetMoreInfo(PdfMetadataKeys.CardCount));
        Assert.Equal("210", info.GetMoreInfo(PdfMetadataKeys.SheetWidth));
        Assert.Equal("63.5", info.GetMoreInfo(PdfMetadataKeys.CardWidth));
        Assert.Equal("False", info.GetMoreInfo(PdfMetadataKeys.DoubleSided));
        Assert.Equal(info.GetTitle(), info.GetMoreInfo(PdfMetadataKeys.PdfId));
    }

    [Fact]
    public void Joining_a_pdf_made_elsewhere_works_and_marks_the_unknown_properties()
    {
        string own = Deck("own", 1);
        string foreign = _workspace.File("foreign.pdf");
        using (var document = new PdfDocument(new PdfWriter(foreign)))
        {
            document.AddNewPage(PageSize.A5);
        }

        var merger = new PdfMerger { Sources = [own, foreign], Destination = _workspace.File("out", "joined.pdf") };
        merger.Merge();

        Assert.Equal(2, PdfInspection.PageCount(merger.Destination));
        using var joined = new PdfDocument(new PdfReader(merger.Destination));
        Assert.Equal("-1", joined.GetDocumentInfo().GetMoreInfo(PdfMetadataKeys.SheetWidth));
    }

    [Fact]
    public void Interleaving_alternates_fronts_and_backs()
    {
        string fronts = Deck("fronts", 10);
        string backs = Deck("backs", 10, project =>
        {
            foreach (PnpTool.Core.Cards.Card card in project.Deck.Cards)
            {
                card.Front = _workspace.Face("b" + Array.IndexOf(project.Deck.Cards, card), "#102030");
            }
        });
        var merger = new PdfMerger { Sources = [fronts, backs], Destination = _workspace.File("out", "duplex.pdf"), Interleave = true };

        Assert.False(merger.Validate().HasError);
        merger.Merge();

        Assert.Equal(4, PdfInspection.PageCount(merger.Destination));
        Assert.True(PdfInspection.Close(Workspace.Colors[0], ColorOfCell(merger.Destination, 1, 0, 0)));
        Assert.True(PdfInspection.Close("#102030", ColorOfCell(merger.Destination, 2, 0, 0)));
        Assert.True(PdfInspection.Close(Workspace.Colors[9], ColorOfCell(merger.Destination, 3, 0, 0)));
        Assert.True(PdfInspection.Close("#102030", ColorOfCell(merger.Destination, 4, 0, 0)));
    }

    [Fact]
    public void Merge_requests_are_checked()
    {
        string two = Deck("two", 10);
        string one = Deck("one", 1);

        Assert.True(new PdfMerger { Sources = [two], Destination = "x.pdf" }.Validate().HasError);
        Assert.True(new PdfMerger { Sources = [two, one] }.Validate().HasError);
        Assert.True(new PdfMerger { Sources = [two, one], Destination = "x.pdf", Interleave = true }.Validate().HasError);
        Assert.True(new PdfMerger { Sources = [two, one, one], Destination = "x.pdf", Interleave = true }.Validate().HasError);
        AppError error = new PdfMerger { Sources = [], Interleave = true }.Validate();
        Assert.DoesNotContain("Need Translation", error.Message);
        Assert.False(new PdfMerger { Sources = [two, two], Destination = "x.pdf", Interleave = true }.Validate().HasError);
    }

    // ------------------------------------------------------------ page size and alignment

    [Fact]
    public void Sheet_size_changes_and_the_content_keeps_its_size()
    {
        string file = Deck("deck", 10);
        var letter = new UnitPoint { X = Unit.FromPoint(612), Y = Unit.FromPoint(792) };

        string resized = PdfPageTools.ChangePageSize(file, letter);

        Assert.Equal(_workspace.File("out", "deck_NewSize.pdf"), resized);
        Assert.Equal(2, PdfInspection.PageCount(resized));
        PointF size = PdfPageTools.PageSize(resized);
        Assert.Equal(612, size.X, 1);
        Assert.Equal(792, size.Y, 1);
        Assert.Equal(595.28, PdfPageTools.PageSize(file).X, 1);
        PlacedImage card = PdfInspection.ImagesOn(resized, 1)[0];
        Assert.Equal(180, card.Width, 1);
        Assert.Equal(252, card.Height, 1);
    }

    [Theory]
    [InlineData("1;3", new[] { 0, 2 })]
    [InlineData("2-4", new[] { 1, 2, 3 })]
    [InlineData("1;4-5", new[] { 0, 3, 4 })]
    [InlineData("4-5;1", new[] { 0, 3, 4 })]
    [InlineData("-2", new[] { 0, 1 })]
    [InlineData("5-", new[] { 4, 5 })]
    [InlineData("3;3;9", new[] { 2 })]
    [InlineData("", new int[0])]
    public void Page_lists_are_read(string text, int[] expected)
    {
        Assert.Equal(expected, PdfPageTools.ParsePages(6, text));
    }

    [Fact]
    public void Alignment_moves_only_the_chosen_pages()
    {
        string file = Deck("deck", 10);
        string aligned = _workspace.File("out", "aligned.pdf");
        var offset = new UnitPoint { X = Unit.FromPoint(10), Y = Unit.FromPoint(-6) };

        PdfPageTools.Align(file, aligned, null, PageSelection.Even, offset, 0);

        using var document = new PdfDocument(new PdfReader(aligned));
        Rectangle first = document.GetPage(1).GetMediaBox();
        Rectangle second = document.GetPage(2).GetMediaBox();
        Assert.Equal(0, first.GetX(), 2);
        Assert.Equal(10, second.GetX(), 2);
        Assert.Equal(-6, second.GetY(), 2);
        Assert.Equal(PageWidth, second.GetWidth(), 1);
    }

    [Fact]
    public void Alignment_can_be_limited_to_listed_pages()
    {
        string file = Deck("deck", 20);
        string aligned = _workspace.File("out", "aligned.pdf");

        PdfPageTools.Align(file, aligned, "1;3", PageSelection.Listed, new UnitPoint { X = Unit.FromPoint(4), Y = Unit.FromPoint(0) }, 0);

        using var document = new PdfDocument(new PdfReader(aligned));
        Assert.Equal([4f, 0f, 4f], Enumerable.Range(1, 3).Select(page => document.GetPage(page).GetMediaBox().GetX()));
    }

    [Fact]
    public void Alignment_angle_turns_the_content_about_the_centre_of_the_sheet()
    {
        // One card at the top left; turned half round it is at the bottom right.
        string file = Deck("deck", 1);
        string turned = _workspace.File("out", "turned.pdf");

        PdfPageTools.Align(file, turned, null, PageSelection.All, new UnitPoint(), 180);

        Assert.True(PdfInspection.Close("#FFFFFF", ColorOfCell(turned, 1, 0, 0)));
        Assert.True(PdfInspection.Close(Workspace.Colors[0], ColorOfCell(turned, 1, 2, 2)));
        Assert.True(PdfInspection.Close(Workspace.Colors[0], ColorOfCell(file, 1, 0, 0)));
        Assert.Equal(PageWidth, PdfPageTools.PageSize(turned).X, 1);
    }

    [Fact]
    public void Back_rotation_of_a_project_turns_only_the_sheets_of_backs()
    {
        Project project = _workspace.Project("Cartas_Standar.pnps", 1, withBacks: true);
        project.Settings.PrintLayout.DoubleSided = true;
        project.Settings.PrintLayout.BackImage = BackImageMode.DifferentBack;
        project.Settings.BackRotation = 180;

        string file = PdfGenerator.Generate(project, _workspace.WorkFolder).Files[0];

        // The front stays at the top left; its back, normally at the top right, is at the bottom left.
        Assert.True(PdfInspection.Close(Workspace.Colors[0], ColorOfCell(file, 1, 0, 0)));
        Assert.True(PdfInspection.Close("#FFFFFF", ColorOfCell(file, 2, 2, 0)));
        Assert.True(PdfInspection.Close(Workspace.BackColor(0), ColorOfCell(file, 2, 0, 2)));
    }

    // ------------------------------------------------------------ files

    [Fact]
    public void Images_of_a_folder_are_sorted_into_front_and_back_by_name()
    {
        string folder = _workspace.File("scans");
        Directory.CreateDirectory(Path.Combine(folder, "back"));
        foreach (string name in new[] { "ace_front.png", "ace_back.png", "king_front.png", "notes.txt" })
        {
            File.WriteAllText(Path.Combine(folder, name), name);
        }

        File.WriteAllText(Path.Combine(folder, "back", "ace_back.png"), "older");

        (int fronts, int backs) = FrontBackSplitter.Split(folder, "_front");

        Assert.Equal((2, 2), (fronts, backs));
        Assert.Empty(Directory.GetFiles(folder));
        Assert.Equal(["ace_front.png", "king_front.png"], Directory.GetFiles(Path.Combine(folder, "front")).Select(Path.GetFileName).Order());
        Assert.Equal("ace_back.png", File.ReadAllText(Path.Combine(folder, "back", "ace_back.png")));
        Assert.True(File.Exists(Path.Combine(folder, "back", "notes.txt")));
    }

    [Fact]
    public void Unique_name_adds_a_number_only_when_the_file_exists()
    {
        string path = _workspace.File("card.png");
        Assert.Equal(path, FileNames.Unique(path));

        File.WriteAllText(path, "x");
        Assert.Equal(_workspace.File("card_0.png"), FileNames.Unique(path));

        File.WriteAllText(_workspace.File("card_0.png"), "x");
        Assert.Equal(_workspace.File("card_1.png"), FileNames.Unique(path));
        Assert.Matches(@"^deck\d{17}$", FileNames.DocumentId("deck"));
    }
}
